<?php
declare(strict_types=1);
require_once __DIR__.'/GiftCatalog.php';
require_once __DIR__.'/Notifications.php';
final class GiftOrders
{
    private const MAX=9007199254740991;
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private function transaction(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$out=$fn();$this->db->commit();return $out;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    private static function uuid(mixed $v):bool{return is_string($v)&&(bool)preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v);}
    private static function text(mixed $v,int $min,int $max):string{if(!is_string($v)||str_contains($v,"\0"))throw new HttpError(400,'Thông tin đặt quà không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);$n=$v===null?-1:strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)throw new HttpError(400,'Kiểm tra tên, điện thoại và địa chỉ.');return $v;}
    private function enabled(array $config):bool{$raw=$this->query("SELECT data FROM jingo_settings WHERE id='features'")->fetchColumn();return $config['enabled']&&($raw===false||!empty(json_decode($raw,true,512,JSON_THROW_ON_ERROR)['giftsEnabled']));}
    private function counters():array{$out=[];foreach($this->query('SELECT id,data FROM jingo_counters ORDER BY id LOCK IN SHARE MODE')->fetchAll(PDO::FETCH_ASSOC) as $r){$c=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);if(($c['status'] ?? '')==='ACTIVE'&&is_string($c['address'] ?? null)&&trim($c['address'])!=='')$out[]=array_intersect_key($c+['id'=>$r['id']],array_flip(['id','name','address','nameEn','addressEn']));}return $out;}
    public function catalog(string $lang='vi'):array
    {
        return $this->transaction(function()use($lang){$c=(new GiftCatalog($this->db))->config();$enabled=$this->enabled($c);$items=[];if($enabled)foreach($c['items'] as $item)if($item['active']){$p=array_intersect_key($item,array_flip(['id','name','description','imageId','price','stock']));if($lang==='en'){$p['name']=($item['nameEn'] ?? '') ?: $item['name'];$p['description']=($item['descriptionEn'] ?? '') ?: $item['description'];}$items[]=$p;}return ['enabled'=>$enabled,'pickupCounters'=>$enabled?$this->counters():[],'shippingFee'=>$c['shippingFee'],'items'=>$items];});
    }
    private function input(array $in):array
    {
        if(array_diff(array_keys($in),['requestId','fulfillment','expectedTotal','name','phone','pickupCounterId','address','lines'])||!self::uuid($in['requestId'] ?? null)||!in_array($in['fulfillment'] ?? null,['PICKUP','DELIVERY'],true)||!is_int($in['expectedTotal'] ?? null)||$in['expectedTotal']<1||$in['expectedTotal']>self::MAX||!is_array($in['lines'] ?? null)||!array_is_list($in['lines'])||count($in['lines'])<1||count($in['lines'])>20)throw new HttpError(400,'Kiểm tra thông tin và giỏ quà.');
        $out=['requestId'=>$in['requestId'],'fulfillment'=>$in['fulfillment'],'expectedTotal'=>$in['expectedTotal'],'name'=>self::text($in['name'] ?? null,2,120),'phone'=>self::text($in['phone'] ?? null,8,25)];if(!preg_match('/^\+?[0-9 ()-]{8,25}$/D',$out['phone']))throw new HttpError(400,'Điện thoại không hợp lệ.');if(array_key_exists('pickupCounterId',$in)){if(!is_string($in['pickupCounterId'])||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$in['pickupCounterId']))throw new HttpError(400,'Mã quầy không hợp lệ.');$out['pickupCounterId']=$in['pickupCounterId'];}$out['address']=self::text(array_key_exists('address',$in)?$in['address']:'',$in['fulfillment']==='DELIVERY'?8:0,500);$out['lines']=[];$seen=[];foreach($in['lines'] as $line){if(!is_array($line)||count($line)!==2||array_diff(array_keys($line),['id','quantity'])||!self::uuid($line['id'] ?? null)||!is_int($line['quantity'] ?? null)||$line['quantity']<1||$line['quantity']>50||isset($seen[strtolower($line['id'])]))throw new HttpError(400,'Giỏ quà có sản phẩm trùng hoặc số lượng không hợp lệ.');$seen[strtolower($line['id'])]=true;$out['lines'][]=['id'=>$line['id'],'quantity'=>$line['quantity']];}return $out;
    }
    private function store(array $c):void{if($c['version']>=2147483647)throw new HttpError(409,'Phiên bản kho vượt giới hạn.');$version=$c['version']+1;unset($c['version']);$this->query("UPDATE jingo_settings SET data=?,version=? WHERE id='gifts'",[json_encode($c,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$version]);}
    private function audit(string $actor,string $action,string $id):void{$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,$action,$id]);}
    public function create(array $in):array
    {
        $input=$this->input($in);$hash=hash('sha256',json_encode($input,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_LINE_TERMINATORS|JSON_THROW_ON_ERROR));return $this->transaction(function()use($input,$hash){$prior=$this->query('SELECT code,data FROM jingo_gift_orders WHERE id=?',[$input['requestId']])->fetch(PDO::FETCH_ASSOC);if($prior){$data=json_decode($prior['data'],true,512,JSON_THROW_ON_ERROR);if(!hash_equals($data['fingerprint'],$hash))throw new HttpError(409,'Mã đặt hàng đã được dùng.');return ['code'=>$prior['code'],'total'=>$data['total']];}$c=(new GiftCatalog($this->db))->config();if(!$this->enabled($c))throw new HttpError(409,'Quà lưu niệm chưa mở bán.');$lines=[];$fee=$input['fulfillment']==='DELIVERY'?$c['shippingFee']:0;$total=$fee;foreach($input['lines'] as $line){$index=array_search($line['id'],array_column($c['items'],'id'),true);if($index===false||!$c['items'][$index]['active']||$c['items'][$index]['stock']<$line['quantity'])throw new HttpError(409,'Một món trong giỏ đã hết hàng hoặc không đủ số lượng.');$p=$c['items'][$index];$total+=$line['quantity']*$p['price'];if($total>self::MAX)throw new HttpError(409,'Tổng tiền vượt giới hạn.');$lines[]=$line+['name'=>$p['name'],'price'=>$p['price']];$c['items'][$index]['stock']-=$line['quantity'];}$pickup=null;if($input['fulfillment']==='PICKUP'){$counters=$this->counters();foreach($counters as $counter)if($counter['id']===($input['pickupCounterId'] ?? null))$pickup=$counter;if((isset($input['pickupCounterId'])||$counters)&&!$pickup)throw new HttpError(409,'Chọn lại quầy nhận hàng.');}if($total!==$input['expectedTotal'])throw new HttpError(409,'Giá đã thay đổi. Tải lại trang để xem giá mới.');$code='JM-G'.strtoupper(bin2hex(random_bytes(6)));$data=$input;$data['address']=$input['fulfillment']==='DELIVERY'?$input['address']:($pickup['address'] ?? '');if($pickup)$data['pickupCounterName']=$pickup['name'];$data['lines']=$lines;$data['shippingFee']=$fee;$data['total']=$total;$data['fingerprint']=$hash;$this->store($c);$this->query('INSERT INTO jingo_gift_orders(id,code,data) VALUES (?,?,?)',[$input['requestId'],$code,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$this->audit('public','gift.create',$input['requestId']);(new Notifications($this->db))->enqueue('GIFT',$code);return ['code'=>$code,'total'=>$total];});
    }
    public function list():array
    {
        $rows=$this->query('SELECT id,code,status,data,created_at FROM jingo_gift_orders ORDER BY created_at DESC,id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['data']=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);unset($r['data']['fingerprint'],$r['data']['requestId']);}unset($r);return ['data'=>$rows];
    }
    public function update(string $id,array $in,string $actor):array
    {
        if(count($in)!==1||!in_array($in['status'] ?? null,['SHIPPING','COMPLETED','CANCELLED'],true))throw new HttpError(400,'Trạng thái đơn quà không hợp lệ.');return $this->transaction(function()use($id,$in,$actor){$o=$this->query('SELECT status,data FROM jingo_gift_orders WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$o)throw new HttpError(404,'Không tìm thấy đơn quà.');if($o['status']===$in['status'])return ['ok'=>true];$data=json_decode($o['data'],true,512,JSON_THROW_ON_ERROR);if(in_array($o['status'],['COMPLETED','CANCELLED'],true)||$in['status']==='SHIPPING'&&$data['fulfillment']!=='DELIVERY')throw new HttpError(409,'Không thể đổi sang trạng thái này.');if($in['status']==='CANCELLED'){$c=(new GiftCatalog($this->db))->config();foreach($data['lines'] as $line){$i=array_search($line['id'],array_column($c['items'],'id'),true);if($i===false)throw new HttpError(409,'Thiếu sản phẩm trong kho. Kiểm tra dữ liệu trước khi hủy.');if($c['items'][$i]['stock']>self::MAX-$line['quantity'])throw new HttpError(409,'Tồn kho vượt giới hạn.');$c['items'][$i]['stock']+=$line['quantity'];}$this->store($c);}$this->query('UPDATE jingo_gift_orders SET status=? WHERE id=?',[$in['status'],$id]);$this->audit($actor,'gift.'.strtolower($in['status']),$id);return ['ok'=>true];});
    }
}
